Status bind_private_shop_command_results_in_candidate(const CommonStore& before_common,const PrivateShopState& before_shops,const PrivateShopCommandResultsState& before,CommonStore& c,const PrivateShopState& shops,PrivateShopCommandResultsState& state,const StableId& actor,Integer sequence,const CommitResult& result,const FamilyState* before_family,const FamilyLegacyState* before_legacy,const FamilyState* family,const FamilyLegacyState* legacy,PrivateShopSubmissionAuthority authority){
 if(authority!=PrivateShopSubmissionAuthority::legacy_actor_api&&authority!=PrivateShopSubmissionAuthority::controlled_player)return common_failure("PrivateShopSubmissionAuthorityInvalid");
 auto valid=validate_private_shop_command_results(before_common,before_shops,&before,before_family,before_legacy);if(!valid.ok)return valid;
 if(state.version!=before.version||!compare_boundary(encode_private_shop_command_results_state(before),encode_private_shop_command_results_state(state)).exact())return common_failure("PrivateShopCommandResultsBeforeChanged");
 auto fresh=private_shop_new_command_fact_sources(before_common,before_shops,c,shops);if(!fresh.ok)return {false,{},fresh.error};
 auto old_controls=read_private_shop_command_control_sources(before_common,before_family,before_legacy);if(!old_controls.ok)return {false,{},old_controls.error};auto controls=read_private_shop_command_control_sources(c,family,legacy);if(!controls.ok)return {false,{},controls.error};std::vector<PrivateShopCommandFactSource> new_controls;std::size_t kept=0;
 for(const auto& source:controls.value){const auto found=std::find_if(old_controls.value.begin(),old_controls.value.end(),[&](const auto& old){return old.id==source.id;});if(found!=old_controls.value.end()){if(found->kind!=source.kind||found->tick!=source.tick||!compare_boundary(found->stable_payload,source.stable_payload).exact())return common_failure("PrivateShopCommandControlOldSourceChanged",source.id);++kept;}else{auto at=source.id.rfind(':');auto n=organization_instance_sequence(source.id,source.id.substr(0,at));if(!n||*n<before_common.state().next_instance_id||source.tick<before_common.tick()||source.tick>c.tick())return common_failure("PrivateShopCommandControlNewSourceMismatch",source.id);new_controls.push_back(source);}}if(kept!=old_controls.value.size())return common_failure("PrivateShopCommandControlOldSourceDeleted");
 const auto* old_sequence=before_common.state().request_sequences.find(actor);const auto* actual_sequence=c.state().request_sequences.find(actor);const auto* cached=c.state().results.find(actor+":"+std::to_string(sequence));auto result_number=organization_instance_sequence(result.result_id,"result");
 if(((authority==PrivateShopSubmissionAuthority::controlled_player||!new_controls.empty())&&before_common.state().metadata.player_actor_id!=actor)||!before_common.actor(actor)||!old_sequence||sequence<=*old_sequence||sequence<1||sequence>2147483647||!actual_sequence||*actual_sequence!=sequence||!cached||cached->get()!=&result||!result.ok||result.kind.empty()||!result_number||*result_number<before_common.state().next_instance_id||*result_number>=c.state().next_instance_id||before_common.revision()==INT64_MAX||result.revision!=before_common.revision()+1||result.revision!=c.revision()||result.tick!=c.tick()||c.state().history.empty())return common_failure("PrivateShopActualCommandResultRequired",result.result_id);
 const auto& history=c.state().history.back();if(history.result_id!=result.result_id||history.kind!=result.kind||history.actor_id!=actor||history.tick!=result.tick)return common_failure("PrivateShopActualCommandHistoryRequired",result.result_id);
 auto original=state;
 auto bind=[&](const auto& values,auto& table)->Status{for(const auto& source:values){auto at=source.id.rfind(':');auto n=organization_instance_sequence(source.id,source.id.substr(0,at));if(!n||*n>=*result_number){return common_failure("PrivateShopSourceAfterActualResult",source.id);}
  PrivateShopCommandResultBinding b;b.id=source.id;b.source_kind=source.kind;b.source_tick=source.tick;b.submitter_actor_id=actor;b.result_id=result.result_id;b.result_kind=result.kind;b.from_tick=before_common.tick();b.result_tick=result.tick;b.allocation_begin=before_common.state().next_instance_id;b.request_seq=sequence;b.revision=result.revision;
  if(!table.insert(source.id,std::move(b))){return common_failure("DuplicatePrivateShopCommandResultBinding",source.id);}
 }return common_success();};
 valid=bind(fresh.value,state.bindings);if(valid.ok)valid=bind(new_controls,state.control_bindings);if(valid.ok)valid=validate_private_shop_command_results(c,shops,&state,family,legacy);if(!valid.ok)state=std::move(original);return valid;
}
